namespace = wild_west

# Bank Robberies
# String of bank robberies in (devastated or frontier state)
wild_west.1 = {
	type = country_event
	event_image = {
		video = "unspecific_vandalized_storefront"
	}
	placement = scope:bank_robbery_state

	on_created_soundeffect = "event:/SFX/UI/Alerts/event_appear"

	icon = "gfx/interface/icons/event_icons/event_newspaper.dds"

	title = wild_west.1.t
	desc = wild_west.1.d
	flavor = wild_west.1.f

	duration = 3

	cooldown = { days = short_modifier_time }

	trigger = {
		NOT = { has_modifier = bank_robberies }
		any_scope_state = {
			any_scope_pop = {
				OR = {
					has_pop_culture = dixie
					has_pop_culture = yankee
				}
			}
			state_population < 100000
			has_building = building_urban_center
		}
	}

	immediate = {
		random_scope_state = {
			limit = {
				any_scope_pop = {
					OR = {
						has_pop_culture = dixie
						has_pop_culture = yankee
					}
				}
				state_population < 100000
				has_building = building_urban_center
			}
			save_scope_as = bank_robbery_state
		}
	}

	option = { # local sheriffs must deal with it
		name = wild_west.1.a
		default_option = yes
		add_modifier = {
			name = bank_robberies
			days = normal_modifier_time
			multiplier = 2
		}
		scope:bank_robbery_state = {
			state_region = {
				add_devastation = 20
			}
		}
	}
	option = { # hire the pinkertons
		name = wild_west.1.b
		add_modifier = {
			name = bank_robberies
			days = normal_modifier_time
		}
		scope:bank_robbery_state = {
			add_radicals_in_state = {
				value = large_radicals
				pop_type = laborers
			}
		}
	}
	option = { # send the national guard
		name = wild_west.1.c
		highlighted_option = yes
		trigger = {
			OR = {
				has_law_or_variant = law_type:law_national_guard
				institution_investment_level = {
					institution = institution_police
					value >= 3
				}
			}
		}
		add_modifier = {
			name = bank_robberies
			days = normal_modifier_time
		}
	}
}

# Raids on the Iron Horse
wild_west.2 = {
	type = country_event
	event_image = {
		video = "unspecific_trains"
	}

	on_created_soundeffect = "event:/SFX/UI/Alerts/event_appear"

	icon = "gfx/interface/icons/event_icons/event_newspaper.dds"

	title = wild_west.2.t
	desc = wild_west.2.d
	flavor = wild_west.2.f

	duration = 3

